mapper.insert:

  SELECT LAST_INSERT_ID()

insert into survey_service_org_report (report_date, service_type_id, service_type_name, 
  entrust_case_num, check_case_num, consignor_org_id, 
  consignor_org_name, survey_org_id, survey_org_name,check_type,positive_num
  )
values (#{reportDate,jdbcType=DATE}, #{serviceTypeId,jdbcType=BIGINT}, #{serviceTypeName,jdbcType=VARCHAR}, 
  #{entrustCaseNum,jdbcType=INTEGER}, #{checkCaseNum,jdbcType=INTEGER}, #{consignorOrgId,jdbcType=BIGINT}, 
  #{consignorOrgName,jdbcType=VARCHAR}, #{surveyOrgId,jdbcType=BIGINT}, #{surveyOrgName,jdbcType=VARCHAR},
  #{checkType,jdbcType=INTEGER}, #{positiveNum,jdbcType=INTEGER}
  )

mapper.select:
select a.services_id serviceTypeId,a.services_name serviceTypeName,ifnull(count(1),0) as checkCaseNum from ( select a.survey_info_id,a.services_id,a.services_name,a.org_id from ( select o.survey_info_id,o.services_id,o.services_name, (case f.parent_id when 0 then f.id else f.parent_id end) as org_id from survey_assign_org o left join survey_franchisee f on o.survey_org_id = f.id left join survey_risk_case_info r on o.survey_info_id = r.id left join survey_consignor n on r.entrust_org_id = n.id where r.delete_flag = 0 and o.delete_flag = 0
) a group by a.org_id,a.survey_info_id ) a group by a.org_id,a.services_id
having a.org_id = #{surveyOrgId,jdbcType=BIGINT}

select a.services_id serviceTypeId,a.services_name serviceTypeName,ifnull(count(1),0) as positiveNum from ( select a.survey_info_id,a.services_id,a.services_name,a.org_id from ( select o.survey_info_id,o.services_id,o.services_name, (case f.parent_id when 0 then f.id else f.parent_id end) as org_id from survey_assign_org o left join survey_franchisee f on o.survey_org_id = f.id left join survey_risk_case_info r on o.survey_info_id = r.id left join survey_consignor n on r.entrust_org_id = n.id left join ( select c.survey_assorg_case_id from survey_investigator_case c where c.delete_flag = 0 and c.is_sun = 1 and c.survey_assorg_case_id is not null group by c.survey_assorg_case_id ) t on o.id = t.survey_assorg_case_id where r.delete_flag = 0 and o.delete_flag = 0 and t.survey_assorg_case_id is not null
) a group by a.org_id,a.survey_info_id ) a group by a.org_id,a.services_id
having a.org_id = #{surveyOrgId,jdbcType=BIGINT}
